// Progression: levels per club, unlocks, stars, Daily streak. Pure functions;
// every "apply*" returns a NEW progress object.
//
// Shift indices are 0-based everywhere (idx 9 = "shift 10").
//
// Levels come from src/data/levels.js (generated by tools/bake.mjs) in a
// compact encoding and are decoded by decodeLevel() from src/engine/codec.js
// (the tiny runtime decoder; dealer.js is bake-time only).
// Every level function also accepts an injected `levels` table (tests).

import { LEVELS } from '../data/levels.js';
import { decodeLevel } from '../engine/codec.js';
import { DAILY_EPOCH, dailyLevel, previewLevel } from '../engine/daily.js';

export { DAILY_EPOCH };

export const PROGRESS_VERSION = 1;
export const UNLOCK_STARS = 15;
export const UNLOCK_SHIFT_IDX = 9; // shift 10
export const CLUB_COUNT = 6;
export const DAILY_RESULTS_KEEP = 60;

/**
 * Progress (persisted by save.js as doorpolicy.save.v1).
 * @typedef {Object} Progress
 * @property {1} v
 * @property {Object<string, {levels:Object<string, 0|1|2|3>, skip:boolean}>} clubs
 *   levels[idx] = best stars for a CLEARED shift (absent = never cleared).
 *   skip = the 🎬 "bribe the doorman" star-gate skip was used to open THIS club.
 * @property {{last:null|string, streak:number, best:number,
 *             results:Object<string, {score:number, max:number, named:boolean, share?:string}>,
 *             started:Object<string, true>}} daily
 *   started[key] = that day's door was begun (a replay, finished or not, is practice).
 * @property {{rounds:number, cleared:number, fired:number, correct:number}} stats
 * @property {boolean} seenTutorial
 */

/** @returns {Progress} */
export function defaultProgress() {
  return {
    v: PROGRESS_VERSION,
    clubs: {},
    daily: { last: null, streak: 0, best: 0, results: {}, started: {} },
    stats: { rounds: 0, cleared: 0, fired: 0, correct: 0 },
    seenTutorial: false,
  };
}

/** Fill in missing fields of a (possibly partial / older) v1 progress. */
export function normalizeProgress(p) {
  const d = defaultProgress();
  if (!p || typeof p !== 'object') return d;
  const clubs = {};
  for (const [k, c] of Object.entries(p.clubs || {})) {
    clubs[k] = { levels: { ...(c?.levels || {}) }, skip: !!c?.skip };
  }
  return {
    ...d,
    ...p,
    v: PROGRESS_VERSION,
    clubs,
    daily: {
      ...d.daily,
      ...(p.daily || {}),
      results: { ...(p.daily?.results || {}) },
      started: { ...(p.daily?.started || {}) },
    },
    stats: { ...d.stats, ...(p.stats || {}) },
    seenTutorial: !!p.seenTutorial,
  };
}

function clubOf(progress, clubId) {
  return progress.clubs?.[clubId] || { levels: {}, skip: false };
}

// ---- levels ---------------------------------------------------------------

/** The LEVELS table (injected or the baked module). */
export function levelsTable(levels) {
  return levels ?? LEVELS;
}

function decode(level) {
  if (!level) return null;
  const decoded = level.target && Array.isArray(level.guests) && level.guests.every((g) => typeof g === 'object');
  return decoded ? level : decodeLevel(level);
}

/**
 * @param {number} clubId 1..6
 * @param {number} idx 0-based shift index
 * @param {object} [levels] injected LEVELS table (tests)
 * @returns {import('../engine/types.js').Level|null}
 */
export function levelFor(clubId, idx, levels) {
  const tab = levelsTable(levels);
  return decode(tab?.clubs?.[clubId]?.[idx] ?? null);
}

/**
 * Daily level for a 'YYYY-MM-DD' key (decoded; wraps beyond the baked year),
 * or null before the first Daily Door (see dailyPreviewLevel).
 */
export function dailyLevelFor(key, levels) {
  if (!(key >= DAILY_EPOCH)) return null;
  try { return dailyLevel(key, levelsTable(levels)) ?? null; } catch { return null; }
}

/** Unscored sneak-peek level shown before the first Daily Door (never a real daily). */
export function dailyPreviewLevel(levels) {
  try { return previewLevel(levelsTable(levels)) ?? null; } catch { return null; }
}

export function shiftsInClub(clubId, levels) {
  return levelsTable(levels)?.clubs?.[clubId]?.length ?? 0;
}

// ---- stars / unlocks ------------------------------------------------------

export function starsFor(progress, clubId, idx) {
  return clubOf(progress, clubId).levels[idx] ?? 0;
}

export function isCleared(progress, clubId, idx) {
  return clubOf(progress, clubId).levels[idx] !== undefined;
}

export function starsInClub(progress, clubId) {
  return Object.values(clubOf(progress, clubId).levels).reduce((a, b) => a + (b | 0), 0);
}

export function totalStars(progress) {
  return Object.keys(progress.clubs || {}).reduce((a, id) => a + starsInClub(progress, id), 0);
}

/**
 * Why a club is locked (null when unlocked).
 * @returns {null|{prev:number, needShift10:boolean, needStars:boolean, have:number, need:number}}
 */
export function lockInfo(progress, clubId) {
  const id = Number(clubId);
  if (id <= 1) return null;
  if (id > CLUB_COUNT) return { prev: id - 1, needShift10: true, needStars: true, have: 0, need: UNLOCK_STARS };
  const prev = id - 1;
  if (!clubUnlocked(progress, prev)) {
    return { prev, needShift10: true, needStars: true, have: starsInClub(progress, prev), need: UNLOCK_STARS };
  }
  const shift10 = isCleared(progress, prev, UNLOCK_SHIFT_IDX);
  const have = starsInClub(progress, prev);
  const starsOk = have >= UNLOCK_STARS || clubOf(progress, id).skip;
  if (shift10 && starsOk) return null;
  return { prev, needShift10: !shift10, needStars: !starsOk, have, need: UNLOCK_STARS };
}

/**
 * Club N (N ≥ 2) is open when club N-1 is open, its shift 10 is cleared, and
 * it holds ≥ 15 stars. The 🎬 skip (useUnlockSkip) waives the STAR gate only
 * (02 §3: "the star gate is soft"); shift 10 must still be cleared.
 */
export function clubUnlocked(progress, clubId) {
  const id = Number(clubId);
  if (id === 1) return true;
  if (!(id >= 2 && id <= CLUB_COUNT)) return false;
  return lockInfo(progress, id) === null;
}

/** True when the skip ad would open the club (shift 10 done, only stars missing, skip unused). */
export function canUseUnlockSkip(progress, clubId) {
  const info = lockInfo(progress, clubId);
  return !!info && !info.needShift10 && info.needStars && !clubOf(progress, clubId).skip
    && clubUnlocked(progress, Number(clubId) - 1);
}

/** Record the once-per-club star-gate skip (after a successful rewarded ad). */
export function useUnlockSkip(progress, clubId) {
  const c = clubOf(progress, clubId);
  if (c.skip) return progress;
  return { ...progress, clubs: { ...progress.clubs, [clubId]: { ...c, levels: { ...c.levels }, skip: true } } };
}

/**
 * Record a finished shift. Keeps the best stars; a loss (stars 0) only updates stats.
 * @param {Progress} progress
 * @param {{club:number, idx:number, stars:number, outcome?:string, correct?:number}} r
 */
export function applyResult(progress, r) {
  const stats = { ...progress.stats };
  stats.rounds = (stats.rounds | 0) + 1;
  if (r.outcome === 'fired') stats.fired = (stats.fired | 0) + 1;
  if (r.stars > 0 || r.outcome === 'cleared') stats.cleared = (stats.cleared | 0) + 1;
  if (r.correct) stats.correct = (stats.correct | 0) + r.correct;
  const next = { ...progress, stats };
  const stars = Math.max(0, Math.min(3, r.stars | 0));
  if (stars > 0) {
    const c = clubOf(progress, r.club);
    const best = Math.max(c.levels[r.idx] ?? 0, stars);
    next.clubs = { ...progress.clubs, [r.club]: { ...c, levels: { ...c.levels, [r.idx]: best } } };
  }
  return next;
}

/** First uncleared shift index in a club (or the last index if all cleared). */
export function nextShift(progress, clubId, levels) {
  const n = shiftsInClub(clubId, levels) || 10;
  for (let i = 0; i < n; i++) if (!isCleared(progress, clubId, i)) return i;
  return n - 1;
}

/** Highest unlocked club and its next shift: where PLAY drops the player. */
export function resumePoint(progress, levels) {
  let club = 1;
  for (let id = CLUB_COUNT; id >= 1; id--) {
    if (clubUnlocked(progress, id) && shiftsInClub(id, levels) > 0) { club = id; break; }
  }
  return { club, idx: nextShift(progress, club, levels) };
}

/**
 * commercialBreak allowed before starting this shift? Never before shift 3 of
 * club 1 (Poki throttles the rest).
 * @param {number} shiftNo 1-based shift number about to start
 * @param {number} [clubId=1]
 */
export function nextBreakAllowed(shiftNo, clubId = 1) {
  return Number(clubId) > 1 || shiftNo >= 3;
}

// ---- daily ----------------------------------------------------------------

function keyToDay(key) {
  const m = /^(\d{4})-(\d{2})-(\d{2})$/.exec(key || '');
  if (!m) return NaN;
  return Math.round(Date.UTC(+m[1], +m[2] - 1, +m[3]) / 86400000);
}

/** Whole UTC days from a to b (b - a). */
export function dayDiff(a, b) {
  return keyToDay(b) - keyToDay(a);
}

/** Daily #N = days since 2026-11-01, plus 1. */
export function dailyNo(key) {
  return dayDiff(DAILY_EPOCH, key) + 1;
}

/** Streak as displayed today: 0 if the last play was before yesterday. */
export function currentStreak(progress, todayKey) {
  const d = progress.daily || {};
  if (!d.last) return 0;
  const diff = dayDiff(d.last, todayKey);
  return diff === 0 || diff === 1 ? d.streak | 0 : 0;
}

export function playedDaily(progress, key) {
  return !!progress.daily?.results?.[key];
}

/** True once the day's door was begun (finished or walked out of). */
export function startedDaily(progress, key) {
  return !!progress.daily?.started?.[key] || playedDaily(progress, key);
}

/**
 * Mark a Daily Door as begun. Any later run of that day is practice (unscored).
 * Keeps only the last DAILY_RESULTS_KEEP days.
 */
export function markDailyStarted(progress, key) {
  const d = progress.daily || defaultProgress().daily;
  if (d.started?.[key]) return progress;
  const started = { ...(d.started || {}), [key]: true };
  const keys = Object.keys(started).sort();
  while (keys.length > DAILY_RESULTS_KEEP) delete started[keys.shift()];
  return { ...progress, daily: { ...d, started } };
}

/**
 * Record a Daily Door. Consecutive UTC days extend the streak; a gap resets to 1;
 * replaying the same day changes nothing (first result stands).
 * @param {Progress} progress
 * @param {string} key 'YYYY-MM-DD'
 * @param {number} score correct judged calls
 * @param {{max?:number, named?:boolean, share?:string}} [extra]
 */
export function applyDaily(progress, key, score, extra = {}) {
  const d = progress.daily || defaultProgress().daily;
  if (d.results?.[key]) return progress;
  let streak;
  const diff = d.last ? dayDiff(d.last, key) : NaN;
  if (diff === 1) streak = (d.streak | 0) + 1;
  else if (diff <= 0) streak = Math.max(1, d.streak | 0); // out-of-order day: keep streak
  else streak = 1;
  const last = !d.last || diff > 0 ? key : d.last;
  const entry = { score, max: extra.max ?? 12, named: !!extra.named };
  if (typeof extra.share === 'string') entry.share = extra.share;
  const results = { ...(d.results || {}), [key]: entry };
  const keys = Object.keys(results).sort();
  while (keys.length > DAILY_RESULTS_KEEP) delete results[keys.shift()];
  return {
    ...progress,
    daily: { ...d, last, streak, best: Math.max(d.best | 0, streak), results },
  };
}
